package com.ventas.integration;
import com.ventas.service.XmlTrialService;import com.ventas.repository.AuthStore;import com.ventas.security.AuthModels.Identity;import com.ventas.security.AuthFailure;import java.time.*;import java.util.*;import java.security.MessageDigest;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="NEGOCIO_DB_INTEGRATION",matches="true") class XmlTrialDatabaseTest{
 @Autowired XmlTrialService service;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;Identity actor;
 @BeforeEach void setup(){var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusHours(1));}
 long count(String table){return jdbc.queryForObject("select count(*) from negocio."+table,Long.class);}
 @Test void sampleDownloadDoesNotCreateCommercialOrFiscalRecords()throws Exception{var before=new HashMap<String,Long>();for(var table:List.of("venta","comprobante_venta","archivo_comprobante","movimiento_caja","movimiento_inventario"))before.put(table,count(table));var d=service.downloadExample(actor,"INTEGRATION_ROLLBACK","B");assertThat(d.nombre()).startsWith("PRUEBA-SIN-VALIDEZ");assertThat(d.sha256()).isEqualTo(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(d.contenido())));for(var table:before.keySet())assertThat(count(table)).isEqualTo(before.get(table));}
 @Test void auditStoresOnlyTrialMetadata(){service.downloadExample(actor,"INTEGRATION_ROLLBACK","F");var data=jdbc.queryForObject("select valor_nuevo::text from negocio.bitacora_evento where accion='VEN.XML_PRUEBA' and pccre='INTEGRATION_ROLLBACK' order by id_evento desc limit 1",String.class);assertThat(data).contains("LOCAL_SIN_FIRMA","EJEMPLO_F").doesNotContain("Invoice","EMISOR","Signature");}
 @Test void missingReceiptIsRejectedWithoutChangingFiscalStatus(){assertThatThrownBy(()->service.preview(actor,Long.MAX_VALUE)).isInstanceOf(AuthFailure.class).hasMessage("Comprobante no encontrado");var s=service.status(actor);assertThat(s.enviosHabilitados()).isFalse();assertThat(s.firmaDigital()).isFalse();assertThat(s.validezTributaria()).isFalse();}
}
